def _get_process_start_time(pid: int) -> Optional[int | float]:
    """Return a stable process start time when the host exposes one.

    Linux exposes a monotonic start tick through ``/proc``.  macOS and
    Windows do not have that filesystem, so fall back to psutil's native
    process creation time.  Scoped gateway locks rely on this value to tell a
    live process from an unrelated process that reused the same PID after a
    reboot.
    """
    stat_path = Path(f"/proc/{pid}/stat")
    try:
        # Field 22 in /proc/<pid>/stat is process start time (clock ticks).
        return int(stat_path.read_text(encoding="utf-8").split()[21])
    except (FileNotFoundError, IndexError, PermissionError, ValueError, OSError):
        pass

    try:
        import psutil  # type: ignore
    except ImportError:
        return None

    try:
        return psutil.Process(int(pid)).create_time()
    except (psutil.Error, ValueError, OSError):
        return None

def _get_process_start_time(pid: int) -> Optional[int]:
    """Per-process start-time fingerprint (PID-reuse guard), or None: ``/proc/<pid>/stat`` field 22
    on Linux, else psutil ``create_time()`` in centiseconds. Units differ per platform; the guard
    only compares same-host values."""
    with contextlib.suppress(IndexError, ValueError, OSError):
        return int(Path(f"/proc/{pid}/stat").read_text(encoding="utf-8").split()[21])
    try:
        import psutil  # type: ignore
        return int(round(psutil.Process(pid).create_time() * 100))
    except Exception:
        return None
